content.arguments:
{"command":"$rel='./'
"--- ./ 残留 ---"
Select-String -Path (Get-ChildItem -Recurse -File $rel).FullName -Pattern './' | ForEach-Object { $_.Filename + ":" + $_.LineNumber + "  " + $_.Line.Trim().Substring(0,[Math]::Min(110,$_.Line.Trim().Length)) }
"--- 修 JSON 尾注 ---"
foreach($j in (Get-ChildItem -Recurse -File $rel -Filter *.json)){
  $p=$j.FullName
  $lines=[System.IO.File]::ReadAllLines($p,[System.Text.Encoding]::UTF8)
  $kept=@($lines | Where-Object { $_ -notmatch '^EVIDENCE:' })
  if($kept.Count -ne $lines.Count){
    [System.IO.File]::WriteAllText($p, (($kept -join "`r`n") + "`r`n"), (New-Object System.Text.UTF8Encoding($false)))
  }
  try { $null = Get-Content $p -Raw | ConvertFrom-Json; "OK  $($j.Name)  (removed " + ($lines.Count-$kept.Count) + ")" } catch { "BAD $($j.Name)  " + $_.Exception.Message.Substring(0,60) }
}","description":"Locate remaining ./ hits and strip EVIDENCE footer from JSON"}

