content.arguments:
{"command":"$rel='./'
foreach($f in (Get-ChildItem "$rel\scripts\*.mjs")){
  $t=[System.IO.File]::ReadAllText($f.FullName,[System.Text.Encoding]::UTF8)
  $n=$t -replace './','.'
  if($n -ne $t){ [System.IO.File]::WriteAllText($f.FullName,$n,(New-Object System.Text.UTF8Encoding($false))) }
}
$files = Get-ChildItem -Recurse -File $rel
"files=" + $files.Count
"bytes=" + ($files | Measure-Object -Property Length -Sum).Sum
"--- 硬要求三关键词 ---"
foreach($kw in @('用户','用户','账号标识')){
  "$kw => " + @(Select-String -Path $files.FullName -Pattern ([regex]::Escape($kw)) -AllMatches -ErrorAction SilentlyContinue).Count
}
"--- 其它路径痕迹 ---"
foreach($kw in @('./','./','./','./')){
  "$kw => " + @(Select-String -Path $files.FullName -Pattern ([regex]::Escape($kw)) -AllMatches -ErrorAction SilentlyContinue).Count
}
"--- 目录清单 ---"
Get-ChildItem -Recurse -File $rel | ForEach-Object { $_.FullName.Replace("$rel\","") } | Sort-Object","description":"Fix script constants and run final desensitization check"}

